package gin

import (
	"errors"
	"fmt"
	"testing"
)

func TestZZFinalUnwrap(t *testing.T) {
	inner := TestErr("some error")

	// pointer direct
	if !errors.Is(&Error{Err: inner, Type: ErrorTypeAny}, inner) {
		t.Fatal("pointer errors.Is")
	}
	// value direct
	var v error = Error{Err: inner, Type: ErrorTypeAny}
	if !errors.Is(v, inner) {
		t.Fatal("value errors.Is")
	}
	var te TestErr
	if !errors.As(v, &te) {
		t.Fatal("value errors.As")
	}
	if errors.Unwrap(v) != error(inner) {
		t.Fatal("value errors.Unwrap")
	}
	// value wrapped by fmt.Errorf
	w := fmt.Errorf("wrapped: %w", Error{Err: inner, Type: ErrorTypeAny})
	if !errors.Is(w, inner) {
		t.Fatal("wrapped value errors.Is")
	}
	var te2 TestErr
	if !errors.As(w, &te2) {
		t.Fatal("wrapped value errors.As")
	}
	// nested values
	n := Error{Err: Error{Err: inner, Type: ErrorTypeAny}, Type: ErrorTypeAny}
	if !errors.Is(n, inner) || errors.Unwrap(errors.Unwrap(n)) != error(inner) {
		t.Fatal("nested value")
	}
	// pointer still works everywhere
	var pe *Error
	if !errors.As(fmt.Errorf("%w", &Error{Err: inner, Type: ErrorTypeAny}), &pe) {
		t.Fatal("pointer errors.As(*Error)")
	}
	// value implements both interfaces
	var _ error = Error{}
	var _ interface{ Unwrap() error } = Error{}
}
EOF
